import org.slf4j.Logger

class LoggingService(private val log: Logger) {
    fun bad(obj: Any) {
        log.debug(obj.toString())
    }
}

import org.slf4j.Logger

class User(val name: Any)
class LoggingService(private val log: Logger) {
    fun bad(user: User) {
        log.trace(user.name.toString())
    }
}

import org.slf4j.Logger

class LoggingService(private val log: Logger) {
    fun good(obj: Any) {
        log.debug("{}", obj)
    }
}

import org.slf4j.Logger

class LoggingService(private val log: Logger) {
    fun good(item: Any) {
        log.info("Processing {}", item)
    }
}

class KotlinLogger {
    fun debug(message: () -> String) = message()
}

class LoggingService(private val logger: KotlinLogger) {
    fun good(obj: Any) {
        logger.debug { "Processing: $obj" }
    }
}
